"""Variant-aware PuddleDuck web-app manifest helpers.

The browser-facing manifest, icon, and initial HTML endpoints use these pure
helpers so they remain testable without importing the hardware-heavy runtime
server.
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import Any, Dict, Iterable, Mapping, Optional, Sequence, Tuple
from urllib.parse import urlencode, urlparse


SUPPORTED_PWA_DUCKS: Tuple[str, ...] = (
    "besh",
    "grek",
    "oskar",
    "red",
    "patch",
)
PWA_MANIFEST_ICON_SIZES: Tuple[int, ...] = (192, 512)
PWA_TOUCH_ICON_SIZE = 192
PWA_DUCK_LABELS = {
    "besh": "Besh",
    "grek": "Grek",
    "oskar": "Oskar",
    "red": "Red",
    "patch": "Patch",
}


def normalize_pwa_duck(
    value: Any,
    *,
    supported: Sequence[str] = SUPPORTED_PWA_DUCKS,
) -> str:
    """Return a supported lowercase variant or ``auto``."""

    text = str(value or "auto").strip().lower()
    allowed = frozenset(str(item or "").strip().lower() for item in supported)
    return text if text in allowed else "auto"


def duck_from_robot_name(
    value: Any,
    *,
    supported: Sequence[str] = SUPPORTED_PWA_DUCKS,
) -> str:
    text = str(value or "").strip().lower()
    for duck in supported:
        normalized = str(duck or "").strip().lower()
        if (
            text == normalized
            or text.endswith(f"_{normalized}")
            or text.endswith(f"-{normalized}")
        ):
            return normalized
    return "auto"


def duck_from_hostname(
    value: Any,
    *,
    supported: Sequence[str] = SUPPORTED_PWA_DUCKS,
) -> str:
    """Resolve a Duck from the first label of a browser-visible hostname.

    The body hostname follows Duck identity (for example ``patch.local``).
    Accept bare hosts, hosts with ports, and complete URLs so the web server can
    use either ``Host`` or ``X-Forwarded-Host`` without special casing Caddy.
    """

    text = str(value or "").strip()
    if not text:
        return "auto"
    try:
        parsed = urlparse(text if "://" in text else f"//{text}")
        hostname = str(parsed.hostname or "").strip().lower().rstrip(".")
    except (TypeError, ValueError):
        hostname = ""
    if not hostname:
        return "auto"
    return normalize_pwa_duck(hostname.split(".", 1)[0], supported=supported)


def duck_from_options(
    value: Any,
    *,
    supported: Sequence[str] = SUPPORTED_PWA_DUCKS,
) -> str:
    candidates = []
    if isinstance(value, Mapping):
        candidates.extend(str(key) for key, enabled in value.items() if enabled)
    elif isinstance(value, Iterable) and not isinstance(value, (str, bytes, bytearray)):
        candidates.extend(str(item) for item in value)
    else:
        candidates.append(str(value or ""))

    for candidate in candidates:
        text = candidate.strip().lower()
        direct = normalize_pwa_duck(text, supported=supported)
        if direct != "auto":
            return direct
        for duck in supported:
            normalized = str(duck or "").strip().lower()
            if f"duck={normalized}" in text or f"duck:{normalized}" in text:
                return normalized
    return "auto"


def resolve_pwa_duck(
    *,
    explicit: Any = None,
    persisted: Any = None,
    hostname: Any = None,
    robot_name: Any = None,
    options: Any = None,
    supported: Sequence[str] = SUPPORTED_PWA_DUCKS,
) -> str:
    """Resolve icon identity in user-intent order.

    An explicit page, manifest, or icon identity wins, followed by the
    persisted viewer choice. Auto mode falls back to the browser-visible host,
    reported robot suffix, and runtime options. The returned value is a
    supported variant or ``auto``.
    """

    for candidate in (
        normalize_pwa_duck(explicit, supported=supported),
        normalize_pwa_duck(persisted, supported=supported),
        duck_from_hostname(hostname, supported=supported),
        duck_from_robot_name(robot_name, supported=supported),
        duck_from_options(options, supported=supported),
    ):
        if candidate != "auto":
            return candidate
    return "auto"


def pwa_icon_filename(duck: Any, size: int) -> str:
    dimension = int(size)
    if dimension not in PWA_MANIFEST_ICON_SIZES:
        allowed = ", ".join(str(item) for item in PWA_MANIFEST_ICON_SIZES)
        raise ValueError(f"web-app icon size must be one of: {allowed}")
    normalized = normalize_pwa_duck(duck)
    if normalized == "auto":
        return f"puddleduck-icon-{dimension}.png"
    return f"puddleduck-{normalized}-icon-{dimension}.png"


def pwa_icon_candidates(duck: Any, size: int) -> Tuple[str, ...]:
    normalized = normalize_pwa_duck(duck)
    generic = pwa_icon_filename("auto", size)
    if normalized == "auto":
        return (generic,)
    return (pwa_icon_filename(normalized, size), generic)


def resolve_pwa_icon_path(
    roots: Iterable[Path],
    duck: Any,
    size: int,
) -> Optional[Path]:
    """Find selected-variant artwork first, then fall back to the generic icon."""

    normalized_roots = []
    seen = set()
    for root in roots:
        try:
            resolved = Path(root).expanduser().resolve()
        except Exception:
            continue
        key = str(resolved)
        if key in seen:
            continue
        seen.add(key)
        normalized_roots.append(resolved)

    # Prefer selected-variant artwork wherever it is installed. Only after
    # exhausting the user, system, and packaged roots do we fall back to the
    # generic PuddleDuck icon. Within each filename candidate, earlier roots
    # retain normal override precedence.
    for filename in pwa_icon_candidates(duck, size):
        for root in normalized_roots:
            candidate = root / filename
            if candidate.is_file():
                return candidate
    return None


def _file_version(path: Optional[Path]) -> str:
    if path is None:
        return ""
    try:
        stat_result = Path(path).stat()
    except OSError:
        return ""
    return f"{int(stat_result.st_mtime_ns):x}-{int(stat_result.st_size):x}"


def pwa_icon_url(
    duck: Any,
    size: int,
    *,
    icon_path: Optional[Path] = None,
    version: str = "",
) -> str:
    """Return a variant-specific icon URL with a cache-busting file token.

    The Duck is encoded in the URL path rather than only in a query parameter.
    That matters for Safari's long-lived icon database: Besh, Patch, and the
    generic icon must not share one cache key.
    """

    dimension = int(size)
    if dimension not in PWA_MANIFEST_ICON_SIZES:
        allowed = ", ".join(str(item) for item in PWA_MANIFEST_ICON_SIZES)
        raise ValueError(f"web-app icon size must be one of: {allowed}")
    normalized = normalize_pwa_duck(duck)
    token = str(version or "").strip() or _file_version(icon_path)
    query = {"v": token} if token else {}
    suffix = f"?{urlencode(query)}" if query else ""
    return f"/app-icon/{normalized}/{dimension}.png{suffix}"


def pwa_manifest_url(
    duck: Any,
    *,
    icon_paths: Optional[Mapping[int, Optional[Path]]] = None,
    version: str = "",
) -> str:
    """Return a variant-specific manifest URL.

    Including the selected Duck in the path prevents an earlier generic
    manifest from remaining associated with the page in Safari's install UI.
    """

    normalized = normalize_pwa_duck(duck)
    token = str(version or "").strip()
    if not token and icon_paths:
        pieces = [
            f"{size}:{_file_version(icon_paths.get(size))}"
            for size in PWA_MANIFEST_ICON_SIZES
            if _file_version(icon_paths.get(size))
        ]
        token = ".".join(pieces)
    query = {"v": token} if token else {}
    suffix = f"?{urlencode(query)}" if query else ""
    return f"/manifest/{normalized}.webmanifest{suffix}"


def pwa_start_url(duck: Any) -> str:
    """Return the stable root URL used by every installed PuddleDuck app.

    Duck identity belongs in the selected manifest and icon paths, not in the
    page address. The body hostname already carries the robot identity, such as
    ``https://patch.local/``.
    """

    del duck
    return "/"


def build_pwa_manifest(
    duck: Any = "auto",
    *,
    icon_urls: Optional[Mapping[int, str]] = None,
) -> Dict[str, Any]:
    """Build the install manifest for the selected Duck."""

    normalized = normalize_pwa_duck(duck)
    label = PWA_DUCK_LABELS.get(normalized, "")
    description = "PuddleDuck robot control, configuration, diagnostics, and telemetry"
    if label:
        description = f"PuddleDuck {label} robot control, configuration, diagnostics, and telemetry"
    urls = dict(icon_urls or {})
    return {
        "id": "/",
        "name": "PuddleDuck",
        "short_name": "PuddleDuck",
        "description": description,
        "start_url": pwa_start_url(normalized),
        "scope": "/",
        "display": "standalone",
        "background_color": "#0b1118",
        "theme_color": "#0b1118",
        "icons": [
            {
                "src": urls.get(size) or pwa_icon_url(normalized, size),
                "sizes": f"{size}x{size}",
                "type": "image/png",
                "purpose": "any maskable",
            }
            for size in PWA_MANIFEST_ICON_SIZES
        ],
        "puddleduck_duck": normalized,
    }


def _replace_tag_attribute(document: str, element_id: str, attribute: str, value: str) -> str:
    """Replace one quoted attribute on an element selected by its ID."""

    element = re.compile(
        rf"(<[^>]*\bid=(['\"]){re.escape(element_id)}\2[^>]*>)",
        flags=re.IGNORECASE,
    )
    match = element.search(document)
    if not match:
        return document
    tag = match.group(1)
    attribute_pattern = re.compile(
        rf"(\b{re.escape(attribute)}\s*=\s*)(['\"])(.*?)\2",
        flags=re.IGNORECASE | re.DOTALL,
    )
    if attribute_pattern.search(tag):
        updated = attribute_pattern.sub(
            lambda item: f"{item.group(1)}{item.group(2)}{value}{item.group(2)}",
            tag,
            count=1,
        )
    else:
        updated = tag[:-1] + f' {attribute}="{value}">'
    return document[: match.start(1)] + updated + document[match.end(1) :]


def render_pwa_index_html(
    document: str,
    duck: Any,
    *,
    manifest_url: str,
    icon_url: str,
) -> str:
    """Render install metadata into the initial HTML response.

    Safari may snapshot Home Screen metadata before application JavaScript has
    finished booting. Supplying the selected manifest and Apple touch icon in
    the first HTML response avoids the generic ``P`` icon winning that race.
    """

    normalized = normalize_pwa_duck(duck)
    label = PWA_DUCK_LABELS.get(normalized, "")
    mobile_title = f"PuddleDuck {label}" if label else "PuddleDuck"
    rendered = str(document)
    rendered = _replace_tag_attribute(rendered, "puddleduck-manifest", "href", manifest_url)
    rendered = _replace_tag_attribute(rendered, "puddleduck-icon", "href", icon_url)
    rendered = _replace_tag_attribute(rendered, "puddleduck-apple-touch-icon", "href", icon_url)
    rendered = _replace_tag_attribute(
        rendered,
        "puddleduck-apple-mobile-web-app-title",
        "content",
        mobile_title,
    )

    html_pattern = re.compile(r"<html\b([^>]*)>", flags=re.IGNORECASE)
    html_match = html_pattern.search(rendered)
    if html_match:
        attrs = html_match.group(1)
        data_pattern = re.compile(r"\sdata-puddleduck-duck=(['\"])(.*?)\1", flags=re.IGNORECASE)
        if data_pattern.search(attrs):
            attrs = data_pattern.sub(f' data-puddleduck-duck="{normalized}"', attrs, count=1)
        else:
            attrs += f' data-puddleduck-duck="{normalized}"'
        rendered = rendered[: html_match.start()] + f"<html{attrs}>" + rendered[html_match.end() :]
    return rendered
